"""Generates the sync resource files (`_sync.py`) from their hand-written async
counterparts (`_async.py`), using the `unasync` library. Run with
`uv run python scripts/generate_sync.py` after editing any `_async.py` file, then commit
the regenerated `_sync.py` alongside it.
"""

import pathlib
import subprocess
import sys

import unasync

_GENERATED_HEADER = (
    "# File generated by scripts/generate_sync.py from the neighboring _async.py. "
    "Do not edit by hand.\n"
)

_ASYNC_FILES = [
    "src/amzn_selling_partner/reports/_async.py",
    "src/amzn_selling_partner/vendor/orders/_async.py",
]

_RULES = [
    unasync.Rule(
        fromdir="reports/_async.py",
        todir="reports/_sync.py",
        additional_replacements={
            "AsyncReports": "Reports",
            "AsyncReportsWithRawResponse": "ReportsWithRawResponse",
            "AsyncClient": "Client",
        },
    ),
    unasync.Rule(
        fromdir="orders/_async.py",
        todir="orders/_sync.py",
        additional_replacements={
            "AsyncOrders": "Orders",
            "AsyncOrdersWithRawResponse": "OrdersWithRawResponse",
            "AsyncClient": "Client",
        },
    ),
]


def main() -> None:
    repo_root = pathlib.Path(__file__).resolve().parent.parent
    unasync.unasync_files([str(repo_root / path) for path in _ASYNC_FILES], _RULES)

    sync_paths = []
    for async_path in _ASYNC_FILES:
        sync_path = repo_root / async_path.replace("_async.py", "_sync.py")
        content = sync_path.read_text()
        if not content.startswith(_GENERATED_HEADER):
            sync_path.write_text(_GENERATED_HEADER + content)
        sync_paths.append(str(sync_path))

    # Token-level unasync doesn't reflow lines, so the shorter sync output (no `async `/
    # `await ` tokens) often needs re-wrapping to match this repo's formatting.
    subprocess.run([sys.executable, "-m", "ruff", "format", *sync_paths], check=True)  # noqa


if __name__ == "__main__":
    main()
